window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-82dcb8a05008a049"]={"versions": [{"id": "FIG-82dcb8a05008a049", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DEM</code>, <code>DET</code> und <code>BSWM</code>.</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN Driver</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN Driver</code> verläuft der Benachrichtigungspfad aufwärts über das <code>CAN Interface</code> zum <code>CAN State Manager</code>.</li>\n<li>Der <code>CAN State Manager</code> verzweigt die Fehlermeldung parallel:</li>\n<li>an <code>DEM</code> (Diagnostic Event Manager) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM),</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>, um den Controller zu reinitialisieren bzw. wiederherzustellen,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DET</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Basistreiber-Schicht (<code>CAN Driver</code>) ist ausschließlich für die Timeout-Detektion und Ausführung der Reinitialisierung zuständig, besitzt jedoch keine autonome Entscheidungsinstanz zur Systemwiederherstellung.</li>\n<li>Die zentrale Koordination und Zustandsführung für den Fehlerfall obliegt dem <code>CAN State Manager</code> (CanSM).</li>\n<li>Die BSW-Architektur muss sicherstellen, dass sowohl Diagnose (<code>DEM</code>) als auch Modusmanagement (<code>BSWM</code>) und Kommunikationsmanagement (<code>ComM</code>) konsistent benachrichtigt werden und Applikationen über den Ausfall via RTE in Kenntnis gesetzt werden.</li>\n</ul>"}, {"id": "FIG-903060eb748e9f83", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DEM</code>, <code>DET</code> und <code>BSWM</code>.</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN Driver</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN Driver</code> verläuft der Benachrichtigungspfad aufwärts über das <code>CAN Interface</code> zum <code>CAN State Manager</code>.</li>\n<li>Der <code>CAN State Manager</code> verzweigt die Fehlermeldung parallel:</li>\n<li>an <code>DEM</code> (Diagnostic Event Manager) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM),</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>, um den Controller zu reinitialisieren bzw. wiederherzustellen,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DET</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Basistreiber-Schicht (<code>CAN Driver</code>) ist ausschließlich für die Timeout-Detektion und Ausführung der Reinitialisierung zuständig, besitzt jedoch keine autonome Entscheidungsinstanz zur Systemwiederherstellung.</li>\n<li>Die zentrale Koordination und Zustandsführung für den Fehlerfall obliegt dem <code>CAN State Manager</code> (CanSM).</li>\n<li>Die BSW-Architektur muss sicherstellen, dass sowohl Diagnose (<code>DEM</code>) als auch Modusmanagement (<code>BSWM</code>) und Kommunikationsmanagement (<code>ComM</code>) konsistent benachrichtigt werden und Applikationen über den Ausfall via RTE in Kenntnis gesetzt werden.</li>\n</ul>"}, {"id": "FIG-2f1ed23b6fc344ff", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DEM</code>, <code>DET</code> und <code>BSWM</code>.</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN Driver</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN Driver</code> verläuft der Benachrichtigungspfad aufwärts über das <code>CAN Interface</code> zum <code>CAN State Manager</code>.</li>\n<li>Der <code>CAN State Manager</code> verzweigt die Fehlermeldung parallel:</li>\n<li>an <code>DEM</code> (Diagnostic Event Manager) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM),</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>, um den Controller zu reinitialisieren bzw. wiederherzustellen,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DET</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Basistreiber-Schicht (<code>CAN Driver</code>) ist ausschließlich für die Timeout-Detektion und Ausführung der Reinitialisierung zuständig, besitzt jedoch keine autonome Entscheidungsinstanz zur Systemwiederherstellung.</li>\n<li>Die zentrale Koordination und Zustandsführung für den Fehlerfall obliegt dem <code>CAN State Manager</code> (CanSM).</li>\n<li>Die BSW-Architektur muss sicherstellen, dass sowohl Diagnose (<code>DEM</code>) als auch Modusmanagement (<code>BSWM</code>) und Kommunikationsmanagement (<code>ComM</code>) konsistent benachrichtigt werden und Applikationen über den Ausfall via RTE in Kenntnis gesetzt werden.</li>\n</ul>"}, {"id": "FIG-9f996854a35d41cf", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DET</code> (oben rechts), <code>BSWM</code> und <code>DEM</code> (unten rechts).</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN State Manager</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN State Manager</code> ausgehend verläuft der Benachrichtigungspfad parallel zu folgenden Instanzen:</li>\n<li>an <code>DET</code> (Development Error Tracer) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM) in den Communication Services,</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DEM</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Detektion des CAN Controller Hardware Timeouts ist auf Ebene des <code>CAN State Manager</code> (CanSM) verortet, welcher gleichzeitig als Recovery-Initiator agiert.</li>\n<li>Die Benachrichtigung (<code>Notification</code>) erfolgt an <code>DET</code>, <code>BSWM</code>, <code>ComM</code> und über die <code>RTE</code> an den <code>Application Layer</code>.</li>\n<li>Die Wiederherstellung (<code>Recovery</code>) bindet neben der Basistreiber-Reinitialisierung (<code>CAN Driver</code>) den <code>DEM</code>, <code>BSWM</code>, <code>ComM</code> sowie den <code>Application Layer</code> ein.</li>\n</ul>"}, {"id": "FIG-d5b28d61c7b4f39c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DET</code> (oben rechts), <code>BSWM</code> und <code>DEM</code> (unten rechts).</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN State Manager</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN State Manager</code> ausgehend verläuft der Benachrichtigungspfad parallel zu folgenden Instanzen:</li>\n<li>an <code>DET</code> (Development Error Tracer) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM) in den Communication Services,</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DEM</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Detektion des CAN Controller Hardware Timeouts ist auf Ebene des <code>CAN State Manager</code> (CanSM) verortet, welcher gleichzeitig als Recovery-Initiator agiert.</li>\n<li>Die Benachrichtigung (<code>Notification</code>) erfolgt an <code>DET</code>, <code>BSWM</code>, <code>ComM</code> und über die <code>RTE</code> an den <code>Application Layer</code>.</li>\n<li>Die Wiederherstellung (<code>Recovery</code>) bindet neben der Basistreiber-Reinitialisierung (<code>CAN Driver</code>) den <code>DEM</code>, <code>BSWM</code>, <code>ComM</code> sowie den <code>Application Layer</code> ein.</li>\n</ul>"}, {"id": "FIG-afca70d38489ae1f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DET</code> (oben rechts), <code>BSWM</code> und <code>DEM</code> (unten rechts).</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN State Manager</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN State Manager</code> ausgehend verläuft der Benachrichtigungspfad parallel zu folgenden Instanzen:</li>\n<li>an <code>DET</code> (Development Error Tracer) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM) in den Communication Services,</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DEM</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Detektion des CAN Controller Hardware Timeouts ist auf Ebene des <code>CAN State Manager</code> (CanSM) verortet, welcher gleichzeitig als Recovery-Initiator agiert.</li>\n<li>Die Benachrichtigung (<code>Notification</code>) erfolgt an <code>DET</code>, <code>BSWM</code>, <code>ComM</code> und über die <code>RTE</code> an den <code>Application Layer</code>.</li>\n<li>Die Wiederherstellung (<code>Recovery</code>) bindet neben der Basistreiber-Reinitialisierung (<code>CAN Driver</code>) den <code>DEM</code>, <code>BSWM</code>, <code>ComM</code> sowie den <code>Application Layer</code> ein.</li>\n</ul>"}, {"id": "FIG-5ab777cd1dffea4c", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt die funktionale Architektur und den Informationsfluss zur Behandlung eines CAN-Controller-Hardware-Timeouts innerhalb des AUTOSAR-Schichtenmodells der Classic Platform dar. Es visualisiert als Block- und Schichtenarchitektur die Interaktion zwischen Microcontroller-Hardware, Communication Drivers, Communication Hardware Abstraction, Communication Services, System Services, RTE und Application Layer bei Fehlererkennung, Benachrichtigung und Fehlerbehebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Folgende Komponenten und Schichten sind beteiligt:</p>\n<ul class=\"fig-list\">\n<li><strong>Microcontroller / Hardware</strong>: Microcontroller (<code>µC</code>) mit internem <code>CAN</code>-Controller und <code>SPI</code>-Schnittstelle sowie angebundenem <code>External CAN Controller</code>.</li>\n<li><strong>Communication Drivers</strong>: <code>CAN Driver</code> und <code>SPIHandler Driver</code>.</li>\n<li><strong>I/O Drivers</strong>: <code>DIO Driver</code>.</li>\n<li><strong>Communication Hardware Abstraction</strong>: <code>CAN Interface</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Communication Services</strong>: <code>CAN State Manager</code> (CanSM), <code>Com. Manager</code> (ComM), <code>AUTOSAR COM</code>, <code>CAN NM</code>, <code>Generic NM Interface</code>, <code>PDU Router</code>, <code>IPDU multiplexer</code>, <code>CAN Transport Protocol</code> und <code>DCM Diagnostic</code>.</li>\n<li><strong>System Services</strong>: <code>FIM</code>, <code>DET</code> (oben rechts), <code>BSWM</code> und <code>DEM</code> (unten rechts).</li>\n<li><strong>Laufzeit- und Anwendungsebene</strong>: <code>RTE</code> (Runtime Environment) und <code>Application Layer</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen werden durch gerichtete Signalisierungspfade gegliedert:</p>\n<ul class=\"fig-list\">\n<li>Roter Kreis: Ort der Fehlererkennung (<code>Detection</code>).</li>\n<li>Rote Pfeile: Benachrichtigungskette (<code>Notification</code>).</li>\n<li>Grüner Kreis: Initiator der Wiederherstellung (<code>Recovery initiator</code>).</li>\n<li>Grüne Pfeile: Pfade zur Fehlerbehebung (<code>Recovery</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Ablauf gliedert sich in Fehlererkennung, Signalisierung und Recovery:</p>\n<ol class=\"fig-list\">\n<li><strong>Detection</strong>: Der Timeout der CAN-Controller-Hardware wird im <code>CAN State Manager</code> detektiert (roter Punkt).</li>\n<li><strong>Notification</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vom <code>CAN State Manager</code> ausgehend verläuft der Benachrichtigungspfad parallel zu folgenden Instanzen:</li>\n<li>an <code>DET</code> (Development Error Tracer) in den System Services,</li>\n<li>an <code>BSWM</code> (BswM) in den System Services,</li>\n<li>an den <code>Com. Manager</code> (ComM) in den Communication Services,</li>\n<li>durch die <code>RTE</code> direkt an den <code>Application Layer</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery initiator & Recovery</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Als <code>Recovery initiator</code> fungiert der <code>CAN State Manager</code> (grüner Kreis).</li>\n<li>Von ihm ausgehend erfolgen Recovery-Maßnahmen:</li>\n<li>abwärts über <code>CAN Interface</code> zum <code>CAN Driver</code>,</li>\n<li>aufwärts über die <code>RTE</code> an den <code>Application Layer</code>,</li>\n<li>an <code>BSWM</code> in den System Services,</li>\n<li>an <code>DEM</code> in den System Services,</li>\n<li>an den <code>Com. Manager</code> in den Communication Services.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt normative Relevanz für das Fehlermanagement bei Hardware-Blockaden im CAN-Subsystem:</p>\n<ul class=\"fig-list\">\n<li>Die Detektion des CAN Controller Hardware Timeouts ist auf Ebene des <code>CAN State Manager</code> (CanSM) verortet, welcher gleichzeitig als Recovery-Initiator agiert.</li>\n<li>Die Benachrichtigung (<code>Notification</code>) erfolgt an <code>DET</code>, <code>BSWM</code>, <code>ComM</code> und über die <code>RTE</code> an den <code>Application Layer</code>.</li>\n<li>Die Wiederherstellung (<code>Recovery</code>) bindet neben der Basistreiber-Reinitialisierung (<code>CAN Driver</code>) den <code>DEM</code>, <code>BSWM</code>, <code>ComM</code> sowie den <code>Application Layer</code> ein.</li>\n</ul>"}], "trans": [{"from": "FIG-82dcb8a05008a049", "to": "FIG-903060eb748e9f83", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-903060eb748e9f83", "to": "FIG-2f1ed23b6fc344ff", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2f1ed23b6fc344ff", "to": "FIG-9f996854a35d41cf", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Fehlererkennung (Detection)</strong>: Der rote Punkt für die Fehlererkennung (<code>Detection</code>) wandert von <code>CAN Driver</code> zu <code>CAN State Manager</code>.</li>\n<li><strong>Benachrichtigungspfade (Notification)</strong>:</li>\n<li>Der Benachrichtigungspfad startet nun im <code>CAN State Manager</code> statt im <code>CAN Driver</code>.</li>\n<li>Die Benachrichtigung an die Diagnose-/Fehlerverwaltung geht nun an <code>DET</code> statt an <code>DEM</code> (in der System Services-Schicht wurden zudem die Beschriftungsblöcke für <code>DET</code> und <code>DEM</code> vertauscht: <code>DET</code> steht oben rechts, <code>DEM</code> unten rechts).</li>\n<li>Der Pfad von <code>CAN Driver</code> aufwärts durch <code>Communication Hardware Abstraction</code> (<code>CAN Interface</code>) zum <code>CAN State Manager</code> entfällt.</li>\n<li><strong>Recovery-Pfade (Recovery)</strong>:</li>\n<li>Der Recovery-Pfad zur Systemverwaltung führt nun zu <code>DEM</code> statt zuvor zu <code>DET</code>.</li>\n<li><strong>System Services-Layout</strong>: Die Bezeichnungen von <code>DEM</code> (zuvor oben rechts) und <code>DET</code> (zuvor unten rechts) wurden gegeneinander getauscht.</li>\n</ul>"}, {"from": "FIG-9f996854a35d41cf", "to": "FIG-d5b28d61c7b4f39c", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d5b28d61c7b4f39c", "to": "FIG-afca70d38489ae1f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-afca70d38489ae1f", "to": "FIG-5ab777cd1dffea4c", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Farbgebung</strong>: Der Balken der <code>RTE</code>-Schicht ist nun orange hinterlegt statt hellgrün.</li>\n<li><strong>Typografie / Schriftbild</strong>: Die Schriftart des Diagramms wurde im Rahmen einer Neurenderung auf eine serifenlose Schrift (Arial-artig) umgestellt.</li>\n</ul>"}]};
